import React from "react";
import { Container, Carousel, Button } from "react-bootstrap";

// Video carousel that opens videos in the shared VideoModal.
// Fill `videoList` with YouTube video IDs so we can open embeddable URLs.
const videoList = [
  {
    id: "v1",
    title: "Video 1",
    vid: "OFdPTWqJsns",
    thumb: "https://img.youtube.com/vi/OFdPTWqJsns/hqdefault.jpg",
  },
  {
    id: "v2",
    title: "Video 2",
    vid: "SxwSDKhBJO0",
    thumb: "https://img.youtube.com/vi/SxwSDKhBJO0/hqdefault.jpg",
  },
  {
    id: "v3",
    title: "Video 3",
    vid: "K_erC9pq4eQ",
    thumb: "https://img.youtube.com/vi/K_erC9pq4eQ/hqdefault.jpg",
  },
  {
    id: "v4",
    title: "Video 4",
    vid: "qDPUJ8T5RBg",
    thumb: "https://img.youtube.com/vi/qDPUJ8T5RBg/hqdefault.jpg",
  },
  {
    id: "v5",
    title: "Video 5",
    vid: "oQuOZyQuyKo",
    thumb: "https://img.youtube.com/vi/oQuOZyQuyKo/hqdefault.jpg",
  },
  {
    id: "v6",
    title: "Video 6",
    vid: "2Lfxk5POL5s",
    thumb: "https://img.youtube.com/vi/2Lfxk5POL5s/hqdefault.jpg",
  },
  {
    id: "v7",
    title: "Video 7",
    vid: "AyhMTuKBQ8E",
    thumb: "https://img.youtube.com/vi/AyhMTuKBQ8E/hqdefault.jpg",
  },
  {
    id: "v8",
    title: "Video 8",
    vid: "SxwSDKhBJO0",
    thumb: "https://img.youtube.com/vi/SxwSDKhBJO0/hqdefault.jpg",
  },
  {
    id: "v9",
    title: "Video 8 (moved)",
    vid: "TwbvviSQoco",
    thumb: "https://img.youtube.com/vi/TwbvviSQoco/hqdefault.jpg",
  },
  {
    id: "v9",
    title: "Video 9",
    vid: "PEECqG_vYjY",
    thumb: "https://img.youtube.com/vi/PEECqG_vYjY/hqdefault.jpg",
  },
  {
    id: "v10",
    title: "Video 10",
    vid: "oIHk10w3pVw",
    thumb: "https://img.youtube.com/vi/oIHk10w3pVw/hqdefault.jpg",
  },
  {
    id: "v11",
    title: "Video 11",
    vid: "nqTguWLKDP4",
    thumb: "https://img.youtube.com/vi/nqTguWLKDP4/hqdefault.jpg",
  },
];

export default function Video({ onWatchVideo }) {
  if (videoList.length === 0) return null;

  const handleOpen = (vid) => {
    // construct embed URL with autoplay
    const embed = `https://www.youtube.com/embed/${vid}?autoplay=1&rel=0`;
    if (onWatchVideo) onWatchVideo(embed, vid);
  };

  return (
    <section id="videos" className="video-area section-padding-100">
      <Container>
        <h3 className="mb-4">Videos</h3>
        <Carousel>
          {videoList.map((v) => (
            <Carousel.Item key={v.id}>
              <a
                href="#play"
                onClick={(e) => {
                  e.preventDefault();
                  handleOpen(v.vid);
                }}
              >
                <img
                  className="d-block w-100 rounded"
                  src={v.thumb}
                  alt={v.title}
                  style={{ maxHeight: 480, objectFit: "cover" }}
                />
              </a>
              <Carousel.Caption>
                <h5>{v.title}</h5>
                <p>
                  <Button
                    variant="light"
                    size="sm"
                    onClick={() => handleOpen(v.vid)}
                  >
                    Play
                  </Button>
                </p>
              </Carousel.Caption>
            </Carousel.Item>
          ))}
        </Carousel>
      </Container>
    </section>
  );
}
